```json
{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, service_name, metric, value FROM abnormal_metrics WHERE service_name='user' AND metric='k8s.deployment.available' ORDER BY time", "claim": "user deployment availability drops from 1 to 0 at about 02:51 and stays at 0 for the rest of the window."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n FROM abnormal_traces WHERE service_name='user' GROUP BY 1,2 UNION ALL SELECT service_name, span_name, count(*) FROM normal_traces WHERE service_name='user' GROUP BY 1,2", "claim": "The user service emits spans in the normal period but none at all in the abnormal period."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(avg(duration)/1e6,3) avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' GROUP BY 1", "claim": "Frontend's CheckUser calls to user fail in about 0.02 ms with error status, versus about 0.5 ms normally."}
      ]
    },
    {
      "service": "attractions",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, round(avg(value),2) avg_v FROM abnormal_metrics WHERE service_name='attractions' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY 1,2 UNION ALL SELECT service_name, metric, round(avg(value),2) FROM normal_metrics WHERE service_name='attractions' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY 1,2", "claim": "Attractions container CPU is pinned near 3.8 in the incident, up from 0; memory roughly doubles."},
        {"kind": "trace", "sql": "SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='attractions' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='attractions'", "claim": "Attractions server spans fall from 245 in the normal window to 1 in the abnormal window."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY 1,2", "claim": "Frontend's /cinema, /museums and /restaurants requests all return HTTP 500 in about 0.05 ms."}
      ]
    }
  ],
  "propagation": [
    {"from": "user", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, s.attr_http_response_status_code code, count(*) n FROM abnormal_traces s WHERE s.service_name='frontend' AND s.attr_span_kind='Server' AND s.trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' AND attr_status_code='Error') GROUP BY 1,2,3", "claim": "Frontend requests whose user.CheckUser call fails return HTTP 500 on /user and /reservation."}]},
    {"from": "attractions", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND attr_http_response_status_code>=500 GROUP BY 1,2", "claim": "Frontend's 500 responses are on attractions-backed routes /cinema, /museums and /restaurants, plus user routes."}]}
  ]
}
